def compute_model_placement(gpu_num, models):
    """Build demand-first and standalone-pressure-first placements; return lower max KVPR."""
    def place(order):
        placement = {g: [] for g in range(gpu_num)}
        remaining = [GPU_MEM_SIZE] * gpu_num
        load = [0.0] * gpu_num

        for model in order:
            demand, size = model.req_rate / model.slo, model.model_size
            gpu = min(
                (g for g in range(gpu_num) if size <= remaining[g]),
                key=lambda g: (load[g] + demand) / max(remaining[g] - size, 1e-12),
                default=None,
            )
            if gpu is None:
                return None
            placement[gpu].append(model)
            load[gpu] += demand
            remaining[gpu] -= size

        return placement, max(load[g] / max(remaining[g], 1e-12) for g in range(gpu_num))

    demand_order = sorted(models, key=lambda m: m.req_rate / m.slo, reverse=True)
    pressure_order = sorted(
        models,
        key=lambda m: (m.req_rate / m.slo) / max(GPU_MEM_SIZE - m.model_size, 1e-12),
        reverse=True,
    )
    candidates = [result for result in (place(demand_order), place(pressure_order)) if result]
    if not candidates:
        raise ValueError("Unable to place all models.")
    return min(candidates, key=lambda result: result[1])[0]
